// src/hooks/useFetchBatters.ts
import { useState, useEffect, useRef, useCallback } from "react";

interface UseFetchBattersOptions {
  /** set to false to disable the initial fetch on mount */
  enabled?: boolean;
}

function useFetchBatters<T>(
  { enabled = true }: UseFetchBattersOptions = {}
): {
  data: T[];
  error: string | null;
  isLoading: boolean;
  /** call as refetch(clearData?, getTomorrow?, signal?) */
  refetch: (
    clearData?: boolean,
    getTomorrow?: boolean,
    signal?: AbortSignal
  ) => void;
  /** abort in-flight request */
  cancel: () => void;
} {
  const [data, setData] = useState<T[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const abortControllerRef = useRef<AbortController | null>(null);

  const fetchTopBatters = useCallback(
    async (
      clearData = false,
      getTomorrow = false,
      signal?: AbortSignal
    ) => {
      setIsLoading(true);
      setError(null);

      // if no signal passed, create a new controller
      if (!signal) {
        abortControllerRef.current?.abort();
        const controller = new AbortController();
        abortControllerRef.current = controller;
        signal = controller.signal;
      }

      try {
        const res = await fetch(
          `http://localhost:3001/api/scraper?clear=${clearData}&tomorrow=${getTomorrow}`,
          { signal }
        );
        if (!res.ok) {
          const text = await res.text();
          throw new Error(`Server error: ${res.status} – ${text}`);
        }
        const json: T[] = await res.json();
        setData(json);
      } catch (err: any) {
        if (err.name !== "AbortError") {
          console.error("Error fetching top batters:", err);
          setError("Error fetching top batters");
        }
      } finally {
        setIsLoading(false);
      }
    },
    []
  );

  const cancel = useCallback(() => {
    abortControllerRef.current?.abort();
    setIsLoading(false);
  }, []);

  // only auto-run on mount if enabled === true
  useEffect(() => {
    if (!enabled) return;
    const controller = new AbortController();
    abortControllerRef.current = controller;
    fetchTopBatters(false, false, controller.signal);
    return () => {
      controller.abort();
    };
  }, [enabled, fetchTopBatters]);

  return { data, error, isLoading, refetch: fetchTopBatters, cancel };
}

export default useFetchBatters;
